"""Real independent business calculations run by n8n Code nodes.

Each result is used in durable advisory evidence. Authoritative mutations remain
in backend transactions; these are not a substitute for tenant/consent checks.
"""
# name, evidence key, JS expression, optional gate (failure becomes a real error).
STAGES = {
'intake':[
 ('Validate event identity','event_valid',"typeof r.event_id==='string' && r.event_id.length>0 && r.event_id.length<=200",True),
 ('Validate customer name','name_valid',"typeof r.lead?.name==='string' && r.lead.name.trim().length>0",True),
 ('Validate message size','message_valid',"typeof r.text==='string' && r.text.length>0 && r.text.length<=4000",True),
 ('Authorize supported source','source_valid',"['website','whatsapp','telegram','facebook','instagram','email','crm'].includes(r.lead?.source)",True),
 ('Normalize contact phone','normalized_phone',"String(r.lead?.phone||'').replace(/\\D/g,'')"),
 ('Normalize contact email','normalized_email',"String(r.lead?.email||'').trim().toLowerCase()"),
 ('Resolve contact identity collisions','identity_safe',"new Set(s.leads.filter(l=>(a.normalized_phone&&l.phone===a.normalized_phone)||(a.normalized_email&&l.email===a.normalized_email)||(r.lead?.external_id&&l.external_id===r.lead.external_id&&l.source===r.lead.source)).map(l=>l.id)).size<=1",True),
 ('Detect explicit Arabic or English','language',"/[\\u0600-\\u06ff]/.test(r.text)?'ar':'en'"),
 ('Detect customer opt-out','opt_out_requested',"/stop|unsubscribe|متبعتش|وقف الرسائل|إلغاء/i.test(r.text)"),
 ('Verify literal consent flag','consent_granted',"r.lead?.consent===true && !a.opt_out_requested"),
 ('Identify injection review signals','security_review',"/ignore.{0,30}instructions|system prompt|api.?key|تجاهل.{0,20}تعليمات/i.test(r.text)"),
 ('Calculate preference completeness','preference_completeness',"['budget','location','property_type'].filter(k=>r.lead?.[k]).length/3"),
 ('Measure active adviser workload','adviser_workload',"s.agents.filter(u=>u.active).map(u=>({id:u.id,open:s.leads.filter(l=>l.assigned_to===u.id&&!['Won','Lost'].includes(l.stage)).length}))"),
 ('Require an available adviser','adviser_available',"a.adviser_workload.length>0",True),
 ('Plan consent-aware intake follow-up','followup_plan',"({eligible:a.consent_granted,delay_hours:s.settings.followup_hours,requires_template:r.lead?.source==='whatsapp'})"),
 ('Prepare atomic CRM disposition','intake_disposition',"({contact_merge:'authoritative-backend',qualification_language:a.language,human_review:a.security_review,opt_out:a.opt_out_requested})")],
'qualification':[
 ('Resolve recorded customer','customer_exists',"Boolean(l?.id)",True),
 ('Validate persisted preference bounds','preference_valid',"l.budget>=0&&l.budget<=1e12&&l.bedrooms>=0&&l.bedrooms<=50",True),
 ('Detect preferred conversation language','language',"s.messages.some(m=>m.direction==='inbound'&&/[\\u0600-\\u06ff]/.test(m.body))?'ar':'en'"),
 ('Identify missing qualification fields','missing_fields',"['budget','location','property_type'].filter(k=>!l[k])"),
 ('Audit budget contribution','budget_points',"l.budget>0?25:0"),
 ('Audit location contribution','location_points',"l.location?20:0"),
 ('Audit specification contribution','specification_points',"(l.property_type?15:0)+(l.bedrooms?10:0)"),
 ('Audit contact and consent contribution','contact_points',"(l.phone||l.email?15:0)+(l.consent?15:0)"),
 ('Reconcile persisted qualification score','score_consistent',"l.score===Math.min(100,a.budget_points+a.location_points+a.specification_points+a.contact_points)",True),
 ('Detect viewing intent evidence','viewing_intent',"s.messages.filter(m=>m.direction==='inbound').slice(0,3).some(m=>/viewing|appointment|book|معاينة|معاينه|احجز|موعد/i.test(m.body))"),
 ('Detect urgency evidence','urgent',"s.messages.filter(m=>m.direction==='inbound').slice(0,3).some(m=>/urgent|today|اليوم|النهارده|عاجل/i.test(m.body))"),
 ('Determine authoritative ownership','human_active',"s.control.human_active===1"),
 ('Validate assigned adviser membership','assignment_valid',"!l.assigned_to||s.agents.some(u=>u.id===l.assigned_to)",True),
 ('Validate qualification enum values','enum_valid',"['buy','rent'].includes(l.intent)&&['','Apartment','Villa','Office','Land'].includes(l.property_type)",True),
 ('Require available qualification evidence','evidence_available',"Boolean(l.created_at)&&Number.isFinite(l.score)",True),
 ('Choose safe sales readiness','readiness',"l.opted_out?'opted_out':a.human_active?'human_review':a.missing_fields.length?'exploring':a.viewing_intent?'viewing_ready':'qualified'")],
'matching':[
 ('Require customer inventory context','customer_exists',"Boolean(l?.id)",True),
 ('Validate inventory prices','prices_valid',"s.properties.every(p=>Number.isFinite(p.price)&&p.price>0)",True),
 ('Filter currently available inventory','available_ids',"s.properties.filter(p=>p.status==='Available').map(p=>p.id)"),
 ('Filter transaction intent','intent_ids',"s.properties.filter(p=>a.available_ids.includes(p.id)&&p.intent===l.intent).map(p=>p.id)"),
 ('Apply hard budget constraint','budget_ids',"s.properties.filter(p=>a.intent_ids.includes(p.id)&&(!l.budget||p.price<=l.budget)).map(p=>p.id)"),
 ('Apply hard area constraint','area_ids',"s.properties.filter(p=>a.budget_ids.includes(p.id)&&(!l.location||p.location.toLowerCase().includes(l.location.toLowerCase()))).map(p=>p.id)"),
 ('Apply hard property category','category_ids',"s.properties.filter(p=>a.area_ids.includes(p.id)&&(!l.property_type||p.property_type===l.property_type)).map(p=>p.id)"),
 ('Apply minimum bedrooms','bedroom_ids',"s.properties.filter(p=>a.category_ids.includes(p.id)&&p.bedrooms>=l.bedrooms).map(p=>p.id)"),
 ('Apply minimum floor area','size_ids',"s.properties.filter(p=>a.bedroom_ids.includes(p.id)&&p.size>=l.min_size).map(p=>p.id)"),
 ('Evaluate requested amenities','amenity_fit',"s.properties.filter(p=>a.size_ids.includes(p.id)).map(p=>({id:p.id,missing:l.amenities.filter(x=>!p.amenities.includes(x))}))"),
 ('Verify recommendation ownership','ownership_valid',"s.matches.every(p=>s.properties.some(x=>x.id===p.id))",True),
 ('Verify recommendation availability','availability_valid',"s.matches.every(p=>p.status==='Available')",True),
 ('Verify recommendations respect budget','budget_valid',"s.matches.every(p=>!l.budget||p.price<=l.budget)",True),
 ('Verify recommendations respect transaction','intent_valid',"s.matches.every(p=>p.intent===l.intent)",True),
 ('Explain inventory rejection funnel','inventory_funnel',"({total:s.properties.length,available:a.available_ids.length,intent:a.intent_ids.length,budget:a.budget_ids.length,area:a.area_ids.length,category:a.category_ids.length,bedrooms:a.bedroom_ids.length,size:a.size_ids.length,verified_matches:s.matches.length})"),
 ('Prepare honest no-match alternatives','alternatives',"s.matches.length?[]:s.properties.filter(p=>a.intent_ids.includes(p.id)).slice(0,5).map(p=>({id:p.id,requires_customer_change:true,over_budget:Boolean(l.budget&&p.price>l.budget),other_area:Boolean(l.location&&p.location!==l.location)}))")],
'appointment':[
 ('Require explicit customer reference','customer_exists',"Boolean(l?.id)",True),
 ('Resolve requested viewing details','booking',"r.appointment||{lead_id:l.id,property_id:s.matches[0]?.id,agent_id:l.assigned_to,start_at:null}"),
 ('Require explicit booking authorization','explicit_booking',"s.demo===true||Boolean(r.appointment)",True),
 ('Resolve real property','property',"s.properties.find(p=>p.id===a.booking.property_id)||null"),
 ('Require currently available property','property_available',"a.property?.status==='Available'",True),
 ('Resolve nominated adviser','adviser',"s.agents.find(u=>u.id===a.booking.agent_id)||null"),
 ('Require active adviser','adviser_active',"Boolean(a.adviser?.active)",True),
 ('Validate customer booking binding','lead_binding',"a.booking.lead_id===l.id",True),
 ('Normalize timezone-aware start','normalized_start',"a.booking.start_at&&/(Z|[+-]\\d{2}:\\d{2})$/.test(a.booking.start_at)?new Date(a.booking.start_at).toISOString():null"),
 ('Require future timezone-aware slot','future_slot',"s.demo===true||Boolean(a.normalized_start&&new Date(a.normalized_start)>new Date())",True),
 ('Calculate reservation duration','duration_minutes',"60"),
 ('Find customer schedule conflicts','customer_conflicts',"s.appointments.filter(x=>x.status==='Booked'&&x.lead_id===l.id&&a.normalized_start&&new Date(x.start_at)<new Date(new Date(a.normalized_start).getTime()+3600000)&&new Date(x.end_at)>new Date(a.normalized_start)).map(x=>x.id)"),
 ('Find adviser schedule conflicts','adviser_conflicts',"s.appointments.filter(x=>x.status==='Booked'&&x.agent_id===a.booking.agent_id&&a.normalized_start&&new Date(x.start_at)<new Date(new Date(a.normalized_start).getTime()+3600000)&&new Date(x.end_at)>new Date(a.normalized_start)).map(x=>x.id)"),
 ('Find property schedule conflicts','property_conflicts',"s.appointments.filter(x=>x.status==='Booked'&&x.property_id===a.booking.property_id&&a.normalized_start&&new Date(x.start_at)<new Date(new Date(a.normalized_start).getTime()+3600000)&&new Date(x.end_at)>new Date(a.normalized_start)).map(x=>x.id)"),
 ('Prepare company-hours verification','business_hours',"({timezone:s.settings.timezone,start:s.settings.business_start,end:s.settings.business_end,authoritative_check:'backend-transaction'})"),
 ('Prepare consent-aware reminder plan','reminder',"({eligible:Boolean(l.consent&&!l.opted_out),human_review:Boolean(s.control.human_active),send_approved:false})")],
'followup':[
 ('Validate follow-up interval','interval_valid',"s.settings.followup_hours>=1&&s.settings.followup_hours<=720",True),
 ('Validate company timezone configuration','timezone_valid',"Boolean(new Intl.DateTimeFormat('en',{timeZone:s.settings.timezone}))",True),
 ('Collect due pending tasks','due_tasks',"s.tasks.filter(t=>t.status==='Pending'&&t.kind!=='handoff'&&new Date(t.due_at)<=new Date())"),
 ('Exclude missing customer references','customer_valid',"a.due_tasks.every(t=>s.leads.some(l=>l.id===t.lead_id))",True),
 ('Apply customer follow-up consent','consented_tasks',"a.due_tasks.filter(t=>s.leads.some(l=>l.id===t.lead_id&&l.consent&&!l.opted_out)).map(t=>t.id)"),
 ('Exclude human-owned conversations','automated_tasks',"a.due_tasks.filter(t=>a.consented_tasks.includes(t.id)&&!s.conversation_controls.some(c=>c.lead_id===t.lead_id&&c.human_active)).map(t=>t.id)"),
 ('Identify availability follow-ups','availability_tasks',"a.due_tasks.filter(t=>a.automated_tasks.includes(t.id)&&t.kind==='availability').map(t=>t.id)"),
 ('Identify ordinary follow-ups','ordinary_tasks',"a.due_tasks.filter(t=>a.automated_tasks.includes(t.id)&&t.kind!=='availability').map(t=>t.id)"),
 ('Collect upcoming viewing reminders','upcoming_viewings',"s.appointments.filter(x=>x.status==='Booked'&&new Date(x.start_at)>new Date()&&new Date(x.start_at)<=new Date(Date.now()+86400000)).map(x=>x.id)"),
 ('Identify dormant customer re-engagement','dormant_leads',"s.leads.filter(l=>l.consent&&!l.opted_out&&!['Won','Lost'].includes(l.stage)&&new Date(l.updated_at)<new Date(Date.now()-2592000000)).map(l=>l.id)"),
 ('Identify consented customer retention','retention_leads',"s.leads.filter(l=>l.stage==='Won'&&l.consent&&!l.opted_out).map(l=>l.id)"),
 ('Validate opt-out suppression','consent_safe',"a.automated_tasks.every(id=>a.due_tasks.some(t=>t.id===id&&s.leads.some(l=>l.id===t.lead_id&&l.consent&&!l.opted_out)))",True),
 ('Validate human ownership suppression','ownership_safe',"a.automated_tasks.every(id=>a.due_tasks.some(t=>t.id===id&&!s.conversation_controls.some(c=>c.lead_id===t.lead_id&&c.human_active)))",True),
 ('Validate delivery authorization type','authorization_valid',"typeof s.safety.external_send_enabled==='boolean'",True),
 ('Prepare stable task receipt keys','dedupe_keys',"a.automated_tasks.map(id=>'task:'+id)"),
 ('Build queue-only follow-up policy','queue_policy',"({provider_called:false,requires_live_authorization:true,eligible_tasks:a.automated_tasks.length,reminders:a.upcoming_viewings.length,consent_excluded:a.due_tasks.length-a.consented_tasks.length})")],
'conversation':[
 ('Require customer conversation','customer_exists',"Boolean(l?.id)",True),
 ('Validate conversation history envelope','history_valid',"s.messages.every(m=>['inbound','outbound'].includes(m.direction)&&typeof m.body==='string')",True),
 ('Resolve recent inbound context','inbound',"s.messages.filter(m=>m.direction==='inbound').slice(0,10)"),
 ('Detect customer conversation language','language',"a.inbound.some(m=>/[\\u0600-\\u06ff]/.test(m.body))?'ar':'en'"),
 ('Locate latest inbound timestamp','last_inbound_at',"a.inbound[0]?.created_at||null"),
 ('Evaluate Meta service window','service_window_open',"Boolean(a.last_inbound_at&&new Date(a.last_inbound_at)>new Date(Date.now()-86400000))"),
 ('Identify customer opt-out boundary','opted_out',"Boolean(l.opted_out)"),
 ('Identify proactive consent boundary','proactive_allowed',"Boolean(l.consent&&!l.opted_out)"),
 ('Identify human ownership boundary','human_active',"Boolean(s.control.human_active)"),
 ('Select permitted response class','response_class',"a.opted_out?'suppressed':a.human_active?'human_only':a.service_window_open?'service_reply':'approved_template_required'"),
 ('Validate listing grounding','grounded',"s.matches.every(p=>s.properties.some(x=>x.id===p.id&&x.status==='Available'))",True),
 ('Validate message length boundary','message_lengths_valid',"s.messages.every(m=>m.body.length<=4000)",True),
 ('Validate source channel policy','channel_valid',"['website','whatsapp','telegram','facebook','instagram','email','crm'].includes(l.source)",True),
 ('Require recorded consent representation','consent_valid',"[0,1].includes(l.consent)&&[0,1].includes(l.opted_out)",True),
 ('Prepare agent review context','agent_context',"({missing:['budget','location','property_type'].filter(k=>!l[k]),inventory_ids:s.matches.map(p=>p.id),history_count:a.inbound.length,ownership:a.human_active?'human':'assistant'})"),
 ('Prepare approval-only draft contract','draft_policy',"({send:false,requires_human_approval:true,template_required:l.source==='whatsapp'&&!a.service_window_open,paid_model_authorized:s.safety.model_usage_enabled})")],
'handoff':[
 ('Require customer escalation reference','customer_exists',"Boolean(l?.id)",True),
 ('Validate escalation score','score_valid',"Number.isFinite(l.score)&&l.score>=0&&l.score<=100",True),
 ('Determine escalation priority','priority',"l.score>=65?'High':'Normal'"),
 ('Determine response SLA duration','sla_minutes',"a.priority==='High'?30:120"),
 ('Calculate SLA due timestamp','due_at',"new Date(Date.now()+a.sla_minutes*60000).toISOString()"),
 ('Collect active advisers','active_advisers',"s.agents.filter(u=>u.active)"),
 ('Require available escalation adviser','adviser_available',"a.active_advisers.length>0",True),
 ('Measure adviser open pipeline','workloads',"a.active_advisers.map(u=>({id:u.id,open:s.leads.filter(l=>l.assigned_to===u.id&&!['Won','Lost'].includes(l.stage)).length}))"),
 ('Resolve existing assigned adviser','assigned_adviser',"a.active_advisers.find(u=>u.id===l.assigned_to)||null"),
 ('Require active assigned owner','assigned_owner_valid',"Boolean(a.assigned_adviser)",True),
 ('Find existing handoff task','handoff_tasks',"s.tasks.filter(t=>t.lead_id===l.id&&t.kind==='handoff'&&t.status==='Pending').map(t=>t.id)"),
 ('Validate handoff task uniqueness','handoff_unique',"a.handoff_tasks.length<=1",True),
 ('Collect confirmed viewing context','viewings',"s.appointments.filter(x=>x.lead_id===l.id&&x.status==='Booked').map(x=>({id:x.id,start_at:x.start_at,property_id:x.property_id}))"),
 ('Summarize recorded customer requirements','requirements',"({budget:l.budget,location:l.location,property_type:l.property_type,bedrooms:l.bedrooms,intent:l.intent})"),
 ('Validate supported ownership state','ownership_valid',"[undefined,0,1].includes(s.control.human_active)",True),
 ('Prepare acknowledgement and resolution policy','ownership_policy',"({pause_automated_replies:true,adviser_id:a.assigned_adviser.id,sla_minutes:a.sla_minutes,acknowledgement_required:true,resolution_requires_explicit_resume:true})")],
'reporting':[
 ('Validate CRM stage values','stages_valid',"s.leads.every(l=>typeof l.stage==='string')",True),
 ('Validate recorded commission amounts','commissions_valid',"s.deals.every(d=>d.commission>=0&&d.amount>=0)",True),
 ('Count recorded customer pipeline','pipeline',"Object.fromEntries([...new Set(s.leads.map(l=>l.stage))].map(k=>[k,s.leads.filter(l=>l.stage===k).length]))"),
 ('Measure channel acquisition','sources',"Object.fromEntries([...new Set(s.leads.map(l=>l.source))].map(k=>[k,s.leads.filter(l=>l.source===k).length]))"),
 ('Measure qualified opportunity count','qualified',"s.leads.filter(l=>l.score>=65).length"),
 ('Measure closed-won conversion','conversion_percent',"s.leads.length?100*s.leads.filter(l=>l.stage==='Won').length/s.leads.length:0"),
 ('Separate earned commission revenue','earned_commission',"s.deals.filter(d=>d.status==='Won').reduce((sum,d)=>sum+d.commission,0)"),
 ('Measure recorded sales volume','sales_volume',"s.deals.filter(d=>d.status==='Won').reduce((sum,d)=>sum+d.amount,0)"),
 ('Separate open pipeline from earnings','open_pipeline',"s.deals.filter(d=>d.status==='Open').reduce((sum,d)=>sum+d.amount,0)"),
 ('Measure viewing completion','viewing_completion',"({booked:s.appointments.length,completed:s.appointments.filter(x=>x.status==='Completed').length,no_show:s.appointments.filter(x=>x.status==='No-show').length})"),
 ('Measure adviser conversion','adviser_performance',"s.agents.map(u=>({id:u.id,leads:s.leads.filter(l=>l.assigned_to===u.id).length,won:s.leads.filter(l=>l.assigned_to===u.id&&l.stage==='Won').length}))"),
 ('Validate tenant customer references','references_valid',"s.deals.every(d=>s.leads.some(l=>l.id===d.lead_id))&&s.tasks.every(t=>!t.lead_id||s.leads.some(l=>l.id===t.lead_id))",True),
 ('Measure unresolved follow-up backlog','followup_backlog',"s.tasks.filter(t=>t.status==='Pending'&&new Date(t.due_at)<=new Date()).length"),
 ('Validate report currency representation','currency_valid',"['EGP','AED','SAR','USD'].includes(s.settings.currency)",True),
 ('Validate report percentage bounds','conversion_valid',"a.conversion_percent>=0&&a.conversion_percent<=100",True),
 ('Require timestamped measurement evidence','timestamp_valid',"Number.isFinite(Date.parse(s.generated_at))",True)]}
NAMES = {'intake':'MADAR Omnichannel Intake','qualification':'MADAR Lead Intelligence','matching':'MADAR Property Matching Engine','appointment':'MADAR Viewing Reservations','followup':'MADAR Follow-up Scheduler','conversation':'MADAR WhatsApp Conversation','handoff':'MADAR Human Handoff & Escalation','reporting':'MADAR Sales Reporting'}
